<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRoute,useRouter} from 'vue-router'
import {api} from '../api'
import {questionStages,formatDate} from '../utils/assignments'
import {setCourseExperience} from '../composables/experience'
import StudioFeedback from '../components/StudioFeedback.vue'
const route=useRoute(),router=useRouter(),cases=ref([]),caseDetail=ref(null),attempt=ref(null),answers=ref({}),stage=ref('premorbid'),busy=ref(false),asking=ref(false),error=ref(''),notice=ref(''),latestRun=ref(null)
const stages=questionStages
const current=computed(()=>attempt.value?.answers.find(a=>a.stage===stage.value))
const unsaved=computed(()=>!!attempt.value && (answers.value[stage.value]||'')!==(current.value?.text||''))
const dirty=computed(()=>!!attempt.value && stages.some(s=>(answers.value[s.key]||'')!==(attempt.value.answers.find(a=>a.stage===s.key)?.text||'')))
const feedback=computed(()=>latestRun.value?.answerVersionId===current.value?.id?latestRun.value:attempt.value?.feedback.find(f=>f.answerVersionId===current.value?.id))
const stale=computed(()=>unsaved.value || (feedback.value && feedback.value.answerVersionId!==current.value?.id))
const canAsk=computed(()=>!!current.value?.text.trim() && !unsaved.value && !attempt.value?.submittedAt && !busy.value && !asking.value && feedback.value?.status!=='pending')
function accept(value,reset=true){if(reset){attempt.value=value;answers.value=Object.fromEntries(stages.map(s=>[s.key,value.answers.find(a=>a.stage===s.key)?.text||'']))}else{attempt.value={...attempt.value,feedback:value.feedback,submittedAt:value.submittedAt}}}
async function load(){busy.value=true;error.value='';try{cases.value=await api('/studio/cases');if(route.query.course)cases.value=cases.value.filter(c=>c.courseId===route.query.course);if(route.params.caseId){const own=await api(`/studio/cases/${route.params.caseId}/attempt`);const context=await api(`/studio/attempts/${own.id}`);caseDetail.value=context.caseDetail;setCourseExperience(context.attempt.isPractice);accept(context.attempt)}}catch(e){error.value=e.message;if(e.status===428)await router.replace('/student/profile')}finally{busy.value=false}}
async function save(submit=false){if(submit&&!confirm(attempt.value.isPractice?'提交本人的練習案例後答案將鎖定，不計入正式學生歷程。確定提交？':'正式提交後答案將鎖定；教師／助教可查看這份作答及對應 AI 文字回饋。確定提交？'))return;busy.value=true;error.value='';notice.value='';try{accept(await api(`/studio/attempts/${attempt.value.id}`,{method:'PUT',body:{expectedVersion:attempt.value.version,answers:answers.value,submit}}));notice.value=submit?(attempt.value.isPractice?'案例練習已提交。':'案例作答已正式提交。'):'四階段草稿已儲存。'}catch(e){error.value=e.message}finally{busy.value=false}}
async function ask(){if(!canAsk.value)return;asking.value=true;error.value='';const answerId=current.value.id;try{const result=await api(`/studio/attempts/${attempt.value.id}/feedback`,{method:'POST',body:{answerVersionId:answerId}});latestRun.value=result;accept((await api(`/studio/attempts/${attempt.value.id}`)).attempt,false)}catch(e){error.value=e.message}finally{asking.value=false}}
async function reload(){if(dirty.value && !confirm('重新載入會放棄未儲存修改，請先保留文字。確定繼續？'))return;await load()}
async function refresh(){try{accept((await api(`/studio/attempts/${attempt.value.id}`)).attempt,false)}catch(e){error.value=e.message}}
function guard(){return !dirty.value || confirm('有尚未儲存的作答，確定離開？')}
onBeforeRouteLeave(guard);onBeforeRouteUpdate(guard)
function unload(event){if(dirty.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload));onMounted(load)
</script>
<template><section class="page-heading"><div><p class="eyebrow">S3 · CASE LEARNING</p><h1>{{caseDetail?.title || '案例學習'}}</h1><p class="muted">依案例證據完成四階段分析，在文字回饋中修訂你的推論。</p></div><RouterLink to="/student/profile" v-if="!attempt?.isPractice" class="button secondary">基本資料</RouterLink></section><p v-if="error" class="error-box" role="alert">{{error}} <button class="text-button" @click="reload">重新載入已儲存版本</button></p><p v-if="notice" class="success-box" role="status">{{notice}}</p><section v-if="!caseDetail" class="studio-case-list"><RouterLink v-for="item in cases" :key="item.id" :to="{path:`/student/cases/${item.id}`,query:route.query.course?{course:route.query.course}:{}}" class="surface studio-case-card"><span class="eyebrow">{{item.courseTitle}} · v{{item.versionNo}}</span><h2>{{item.title}}</h2><span>開始／繼續作答 →</span></RouterLink><p v-if="!busy && !cases.length" class="surface form-surface">目前沒有可讀取的已發布案例，請聯絡課程教師或管理者。</p></section><template v-if="caseDetail && attempt"><RouterLink :to="{path:`/courses/${caseDetail.courseId}`,query:{section:'cases'}}" class="back-link">← 返回所屬課程</RouterLink><RouterLink :to="{path:'/student/cases',query:{course:caseDetail.courseId}}" class="back-link">← 返回案例清單</RouterLink><nav class="studio-stage-tabs" aria-label="四階段案例分析"><button v-for="(s,i) in stages" :key="s.key" :class="{active:stage===s.key}" @click="stage=s.key;latestRun=null">{{['①','②','③','④'][i]}} {{s.label}}</button></nav><p class="muted">{{caseDetail.courseTitle}} · 案例版本 {{caseDetail.versionNo}} <span v-if="attempt.submittedAt">· {{attempt.isPractice?'已提交練習':'已正式提交'}} {{formatDate(attempt.submittedAt)}}</span></p><div class="studio-three-pane"><section class="surface studio-pane"><h2>案例原文</h2><p class="studio-prose">{{caseDetail.material}}</p></section><section class="surface studio-pane"><h2>學生作答</h2><p class="studio-structure">{{caseDetail.prompts[stage]}}</p><label :for="`studio-answer-${stage}`">{{stages.find(s=>s.key===stage)?.label}} 作答<textarea :id="`studio-answer-${stage}`" v-model="answers[stage]" rows="18" maxlength="16000" :readonly="!!attempt.submittedAt" :disabled="busy"></textarea></label><p class="field-hint">{{(answers[stage]||'').length}} / 16000 · {{dirty?'有未儲存修改':'目前已儲存'}}</p><div class="studio-actions"><button class="button secondary" :disabled="busy || !!attempt.submittedAt || !dirty" @click="save(false)">儲存四階段草稿</button><button class="button primary" :disabled="busy || !!attempt.submittedAt" @click="save(true)">{{attempt.isPractice?'提交練習':'正式提交'}}</button></div><p v-if="attempt.isPractice" class="field-hint">學生體驗可提交本人練習，與正式學生學習歷程及統計分開。案例僅有文字回饋，不計分。</p><details v-if="attempt.answers.some(a=>a.stage===stage)" class="revision-history"><summary>我的已儲存版本</summary><article v-for="answer in attempt.answers.filter(a=>a.stage===stage)" :key="answer.id"><strong>版本 {{answer.revisionNo}}</strong><p class="studio-prose">{{answer.text}}</p></article></details></section><section class="surface studio-pane"><StudioFeedback :feedback="feedback" :stale="stale" :busy="asking" :can-ask="canAsk" :unsaved="unsaved" @ask="ask" @reload="refresh" /></section></div></template></template>
